{"path": "robot_name.py", "content": "import random
import string


class Robot:
    _used = set()

    def __init__(self):
        self._name = None

    @property
    def name(self):
        if self._name is None:
            self._name = self._generate()
        return self._name

    def _generate(self):
        while True:
            candidate = (
                "".join(random.choices(string.ascii_uppercase, k=2))
                + "".join(random.choices(string.digits, k=3))
            )
            if candidate not in Robot._used:
                Robot._used.add(candidate)
                return candidate

    def reset(self):
        if self._name is not None:
            Robot._used.discard(self._name)
        self._name = None
